func TestValidate_BatchNegativeDoesNotPanic(t *testing.T) {
	in := validInput()
	in.BatchSize = -1
	var err error
	func() {
		defer func() {
			if r := recover(); r != nil {
				t.Fatalf("MakeReleasePlan panicked: %v", r)
