func batchIDs(plan ReleasePlan) []string {
	var out []string
	for _, b := range plan.Batches {
		out = append(out, strings.Join(b.Clusters, ","))
	}
	return out
}

func TestPlan_SpreadByFaultDomain(t *testing.T) {
	in := parsePlan(t, `{
