// that contains invalid raw UTF-8 or an unpaired \uXXXX surrogate escape.
// It performs no business interpretation of the document; numbers are only
// skipped, so a legal number beyond float64 range never disturbs the check.
func checkJSONText(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
