// its span and returns the token's exact raw bytes, which must be a
// double-quoted JSON string. When the span cannot be recognized as one the
// caller's string check is simply skipped: the token has already been
// accepted as a string by encoding/json, so this can only misjudge our own
// bookkeeping, never the document's validity.
func rawStringToken(data []byte, start, end int64) (string, bool) {
	i := int(start)
	for i < int(end) && isJSONSpace(data[i]) {
		i++
	}
	if i >= int(end) || data[i] != '"' {
		return "", false
	}
	return string(data[i:int(end)]), true
}

func isJSONSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

func walkJSONTextObject(dec *json.Decoder, data []byte, path string) error {
	for {
		keyStart := dec.InputOffset()
		tok, err := dec.Token()
		if err != nil {
			return err
		}
