}

// checkDecodedString inspects one decoded JSON string against its exact raw
// spelling: raw is the double-quoted token from the document and decoded is
// the string encoding/json produced. It flags a raw byte that is not valid
// UTF-8 and an unpaired surrogate escape. A genuinely written U+FFFD —
// directly in valid UTF-8 or as the valid escape � — is not flagged,
// and an escaped backslash before "uD800" is literal text, not an escape.
func checkDecodedString(raw string, decoded string) *textCheckError {
	// The quoted token's bytes between the quotes are the raw JSON string
	// contents; check them as UTF-8 so a broken byte cannot hide behind a
	// decoded U+FFFD. Whitespace has already been trimmed by the caller.
	if len(raw) >= 2 && raw[0] == '"' && raw[len(raw)-1] == '"' {
		if !utf8.ValidString(raw[1 : len(raw)-1]) {
			return &textCheckError{kind: invalidTextUTF8}
		}
	}
	if hasUnpairedSurrogate(raw) {
		return &textCheckError{kind: invalidTextSurrogate}
	}
	return nil
}

// hasUnpairedSurrogate scans a raw JSON string token for a \uXXXX escape that
// is an unpaired UTF-16 surrogate. High surrogates must be followed
// immediately by a low surrogate and lows must follow a high; any other
// arrangement is unpaired. A doubled backslash ("\\uD800") escapes the
// backslash itself and leaves six ordinary characters, so it is skipped by
// the parity rule for backslashes.
func hasUnpairedSurrogate(raw string) bool {
	pendingHigh := false
	for i := 0; i < len(raw); {
		b := raw[i]
		if b != '\\' {
			if pendingHigh {
				// High surrogate was not immediately followed by its low.
				return true
			}
			// Advance one UTF-8 rune; raw has already been validated as
			// UTF-8 here (check order in checkDecodedString aside, the loop
			// is also used only on quoted tokens), so RuneError cannot arise.
			_, size := utf8.DecodeRuneInString(raw[i:])
			if size == 0 {
				size = 1
			}
			i += size
			continue
		}
		// Escape sequence. Determine how many backslashes introduce it: an
		// even run means the next character is literal text, an odd run means
		// the last backslash introduces the escape that follows.
		j := i
		for j < len(raw) && raw[j] == '\\' {
			j++
		}
		n := j - i
		if n%2 == 0 {
			// Paired backslashes cancel into literal backslashes; resume after
			// them with whatever character follows (which may start another
			// escape, examined on the next iteration).
			if pendingHigh {
				return true
			}
			i = j
			continue
		}
		if j >= len(raw) {
			return pendingHigh // malformed token would already have failed decoding
		}
		switch raw[j] {
		case 'u':
			r, ok := hex4ToRune(raw[j+1:])
			if !ok {
				// Not a \uXXXX sequence (cannot happen for a token encoding
				///json accepted); treat as an ordinary escape.
				if pendingHigh {
					return true
				}
				i = j + 1
				continue
			}
			switch {
			case isHighSurrogate(r):
				if pendingHigh {
					return true // previous high got no low
				}
				pendingHigh = true
			case isLowSurrogate(r):
				if !pendingHigh {
					return true // low without a preceding high
				}
				pendingHigh = false // complete surrogate pair
			default:
				if pendingHigh {
					return true
				}
			}
			i = j + 5 // backslashes + 'u' + 4 hex digits
		default:
			if pendingHigh {
				return true
			}
			i = j + 1
		}
	}
	return pendingHigh
}

// hex4ToRune decodes exactly four hexadecimal digits at s[0:4].
func hex4ToRune(s string) (rune, bool) {
	if len(s) < 4 {
		return 0, false
	}
	var r rune
	for k := 0; k < 4; k++ {
		var d rune
		switch {
		case '0' <= s[k] && s[k] <= '9':
			d = rune(s[k] - '0')
		case 'a' <= s[k] && s[k] <= 'f':
			d = rune(s[k]-'a') + 10
		case 'A' <= s[k] && s[k] <= 'F':
			d = rune(s[k]-'A') + 10
		default:
			return 0, false
		}
		r = r<<4 | d
	}
	return r, true
}

func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }

