	switch e.kind {
	case invalidTextUTF8:
		return fmt.Sprintf("JSON 文本包含无效 UTF-8 字节: %s", e.path)
	default:
		return fmt.Sprintf("JSON 文本包含未配对的 Unicode 代理项转义 (\\uXXXX): %s", e.path)
	}
}

// checkJSONText walks every value in data and rejects the first JSON string
// that contains invalid raw UTF-8 or an unpaired \uXXXX surrogate escape.
// It performs no business interpretation of the document; numbers are only
// skipped, so a legal number beyond float64 range never disturbs the check.
func checkJSONText(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return walkJSONTextValue(dec, data, "$")
}

// walkJSONTextValue consumes one complete JSON value whose first token has
// not been read yet.
func walkJSONTextValue(dec *json.Decoder, data []byte, path string) error {
	start := dec.InputOffset()
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	return walkJSONTextToken(dec, data, path, tok, start)
}

// walkJSONTextToken consumes the remainder of a value given its first token.
// tokenStart is the input offset right before this token was read; combined
// with the decoder's offset after the token it bounds the token's exact raw
// bytes, which is what the string checks inspect (escapes are raw text).
func walkJSONTextToken(dec *json.Decoder, data []byte, path string, tok json.Token, tokenStart int64) error {
	if d, ok := tok.(json.Delim); ok {
		switch d {
		case '{':
			return walkJSONTextObject(dec, data, path)
		case '[':
			return walkJSONTextArray(dec, data, path)
		default:
			return nil
		}
	}
	if s, ok := tok.(string); ok {
		// A root-level document string is legal JSON (if unusual here); the
		// later document-shape validation reports that. The text rule still
		// applies at its own location.
		if err := checkDecodedString(data[tokenStart:dec.InputOffset()], s); err != nil {
			return &invalidTextError{kind: err.kind, path: path}
		}
	}
	return nil // number, bool, null
}

// rawStringToken trims the leading whitespace a decoder token may include in
// its span and returns the token's exact raw bytes, which must be a
// double-quoted JSON string. When the span cannot be recognized as one the
// caller's string check is simply skipped: the token has already been
// accepted as a string by encoding/json, so this can only misjudge our own
// bookkeeping, never the document's validity.
func rawStringToken(data []byte, start, end int64) (string, bool) {
	i := int(start)
	for i < int(end) && isJSONSpace(data[i]) {
		i++
	}
	if i >= int(end) || data[i] != '"' {
		return "", false
	}
	return string(data[i:int(end)]), true
}

func isJSONSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

func walkJSONTextObject(dec *json.Decoder, data []byte, path string) error {
	for {
		keyStart := dec.InputOffset()
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		if d, ok := tok.(json.Delim); ok && d == '}' {
			return nil
		}
		key := tok.(string) // encoding/json guarantees object keys are strings
		if raw, ok := rawStringToken(data, keyStart, dec.InputOffset()); ok {
			if err := checkDecodedString(raw, key); err != nil {
				// A bad member name is reported against the object that owns
				// it, not as a value under the broken name.
				return &invalidTextError{kind: err.kind, path: path}
			}
		}

		valStart := dec.InputOffset()
		vtok, err := dec.Token()
		if err != nil {
			return err
		}
		if err := walkJSONTextToken(dec, data, joinMemberPath(path, key), vtok, valStart); err != nil {
			return err
		}
	}
}

func walkJSONTextArray(dec *json.Decoder, data []byte, path string) error {
	for i := 0; ; i++ {
		elemStart := dec.InputOffset()
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		if d, ok := tok.(json.Delim); ok && d == ']' {
			return nil
		}
		elemPath := fmt.Sprintf("%s[%d]", path, i)
		if err := walkJSONTextToken(dec, data, elemPath, tok, elemStart); err != nil {
			return err
		}
	}
}

// textCheckError distinguishes the two broken-text causes without carrying a
// message, so callers can attach their own location.
type textCheckError struct {
	kind string
}

// checkDecodedString inspects one decoded JSON string against its exact raw
// spelling: raw is the double-quoted token from the document and decoded is
// the string encoding/json produced. It flags a raw byte that is not valid
// UTF-8 and an unpaired surrogate escape. A genuinely written U+FFFD —
// directly in valid UTF-8 or as the valid escape � — is not flagged,
// and an escaped backslash before "uD800" is literal text, not an escape.
func checkDecodedString(raw string, decoded string) *textCheckError {
	// The quoted token's bytes between the quotes are the raw JSON string
	// contents; check them as UTF-8 so a broken byte cannot hide behind a
	// decoded U+FFFD. Whitespace has already been trimmed by the caller.
	if len(raw) >= 2 && raw[0] == '"' && raw[len(raw)-1] == '"' {
		if !utf8.ValidString(raw[1 : len(raw)-1]) {
			return &textCheckError{kind: invalidTextUTF8}
		}
	}
	if hasUnpairedSurrogate(raw) {
		return &textCheckError{kind: invalidTextSurrogate}
	}
	return nil
}

// hasUnpairedSurrogate scans a raw JSON string token for a \uXXXX escape that
// is an unpaired UTF-16 surrogate. High surrogates must be followed
// immediately by a low surrogate and lows must follow a high; any other
// arrangement is unpaired. A doubled backslash ("\\uD800") escapes the
// backslash itself and leaves six ordinary characters, so it is skipped by
// the parity rule for backslashes.
func hasUnpairedSurrogate(raw string) bool {
	pendingHigh := false
	for i := 0; i < len(raw); {
		b := raw[i]
		if b != '\\' {
			if pendingHigh {
				// High surrogate was not immediately followed by its low.
				return true
			}
			// Advance one UTF-8 rune; raw has already been validated as
			// UTF-8 here (check order in checkDecodedString aside, the loop
			// is also used only on quoted tokens), so RuneError cannot arise.
			_, size := utf8.DecodeRuneInString(raw[i:])
			if size == 0 {
				size = 1
			}
			i += size
			continue
		}
		// Escape sequence. Determine how many backslashes introduce it: an
		// even run means the next character is literal text, an odd run means
		// the last backslash introduces the escape that follows.
		j := i
		for j < len(raw) && raw[j] == '\\' {
			j++
		}
		n := j - i
		if n%2 == 0 {
			// Paired backslashes cancel into literal backslashes; resume after
			// them with whatever character follows (which may start another
			// escape, examined on the next iteration).
			if pendingHigh {
				return true
			}
			i = j
			continue
		}
		if j >= len(raw) {
			return pendingHigh // malformed token would already have failed decoding
		}
		switch raw[j] {
		case 'u':
			r, ok := hex4ToRune(raw[j+1:])
			if !ok {
				// Not a \uXXXX sequence (cannot happen for a token encoding
				///json accepted); treat as an ordinary escape.
				if pendingHigh {
					return true
				}
				i = j + 1
				continue
			}
			switch {
			case isHighSurrogate(r):
				if pendingHigh {
					return true // previous high got no low
				}
				pendingHigh = true
			case isLowSurrogate(r):
				if !pendingHigh {
					return true // low without a preceding high
				}
				pendingHigh = false // complete surrogate pair
			default:
				if pendingHigh {
					return true
				}
			}
			i = j + 5 // backslashes + 'u' + 4 hex digits
		default:
			if pendingHigh {
				return true
			}
			i = j + 1
		}
	}
	return pendingHigh
}

// hex4ToRune decodes exactly four hexadecimal digits at s[0:4].
func hex4ToRune(s string) (rune, bool) {
	if len(s) < 4 {
		return 0, false
	}
	var r rune
	for k := 0; k < 4; k++ {
		var d rune
		switch {
		case '0' <= s[k] && s[k] <= '9':
			d = rune(s[k] - '0')
		case 'a' <= s[k] && s[k] <= 'f':
			d = rune(s[k]-'a') + 10
		case 'A' <= s[k] && s[k] <= 'F':
			d = rune(s[k]-'A') + 10
		default:
			return 0, false
		}
		r = r<<4 | d
	}
	return r, true
}

func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }

package darksafe

import (
	"encoding/json"
	"fmt"
	"unicode/utf8"
)

// This file enforces the JSON text rule that encoding/json deliberately does
// not: a document's strings must carry the user's text verbatim, never a
// character substituted for broken input. encoding/json replaces two kinds of
// broken text with the Unicode replacement character U+FFFD and keeps going:
//
//   - a raw byte sequence that is not valid UTF-8 inside a JSON string, and
//   - a \uXXXX escape that is an unpaired UTF-16 surrogate: a high surrogate
//     (U+D800–U+DBFF) not immediately followed by a low surrogate
//     (U+DC00–U+DFFF), or a low surrogate not preceded by a high one.
//
// Both are rejected by the structural walk in plan.go, which visits every
// JSON value — member names and string values alike, in known fields and in
// unknown extra fields, however deeply their objects and arrays nest — so a
// text error is found before any business-field validation or release
// planning. A U+FFFD the user actually wrote (directly in valid UTF-8 or as
// the valid escape �) is itself a legal character and is accepted;
// "\uD800" with the backslash itself escaped ("\\uD800") is ordinary literal
// text, not a Unicode escape, and is accepted as well.

// Text-error markers used by invalidTextError and checkJSONString.
const (
	invalidTextUTF8      = "utf8"
	invalidTextSurrogate = "surrogate"
)

// invalidTextError reports a JSON string whose decoded form cannot be trusted
// to preserve the user's text. path locates the string the same way
// duplicateMemberError does: "$.clusters[0].id" for a member value,
// "$.clusters[1]" for a string array element, and "$.clusters[0].tags" for a
// broken member name (reported against the object that owns the name).
type invalidTextError struct {
	kind string
	path string
}

func (e *invalidTextError) Error() string {
	switch e.kind {
	case invalidTextUTF8:
		return fmt.Sprintf("JSON 文本包含无效 UTF-8 字节: %s", e.path)
	default:
		return fmt.Sprintf("JSON 文本包含未配对的 Unicode 代理项转义 (\\uXXXX): %s", e.path)
	}
}

// rawTokenBytes bounds one token's exact bytes from decoder offsets: it trims
// the insignificant whitespace a token span may start with, returning the
// bytes from the token's first significant byte up to end.
func rawTokenBytes(data []byte, start, end int64) []byte {
	i := int(start)
	for i < int(end) && isJSONSpace(data[i]) {
		i++
	}
	return data[i:int(end)]
}

func isJSONSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

// checkJSONStringToken inspects one string token encoding/json has already
// accepted: raw is the token's exact bytes in the document (the surrounding
// double quotes included) and decoded is the string the decoder produced.
// It flags invalid raw UTF-8 and unpaired surrogate escapes. A genuinely
// written U+FFFD is indistinguishable from a substitution only after decoding,
// which is why the raw token — not the decoded string — is examined.
func checkJSONStringToken(raw []byte, _ string) *invalidTextError {
	if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
		// The token was read as a string, so its span must be quoted; if our
		// offset bookkeeping ever says otherwise, do not second-guess the
		// document on a hunch.
		return nil
	}
	body := raw[1 : len(raw)-1]
	if !utf8.Valid(body) {
		return &invalidTextError{kind: invalidTextUTF8}
	}
	if hasUnpairedSurrogate(body) {
		return &invalidTextError{kind: invalidTextSurrogate}
	}
	return nil
}

// hasUnpairedSurrogate scans the body of a raw JSON string token (quotes
// excluded) for a \uXXXX escape that is an unpaired UTF-16 surrogate. A high
// surrogate escape must be immediately followed by a low surrogate escape and
// a low must follow a high; anything in between — another escape, a literal
// character, end of string — leaves the surrogate unpaired. A doubled
// backslash is an escaped backslash ("\\"), so "\\uD800" leaves the seven
// ordinary characters u, D, 8, 0, 0 after consuming the paired backslashes
// and is not read as a Unicode escape.
func hasUnpairedSurrogate(body []byte) bool {
	pendingHigh := false
	for i := 0; i < len(body); {
		if body[i] != '\\' {
			if pendingHigh {
				return true // high surrogate was not immediately followed by its low
			}
			_, size := utf8.DecodeRune(body[i:])
			if size == 0 {
				size = 1
			}
			i += size
			continue
		}
		// body[i] is a backslash introducing (or, for "\\", pairing with) an
		// escape. A non-unicode escape consumes two bytes total; "\\uD800" is
		// therefore the two-byte escaped backslash plus literal "uD800".
		if i+1 >= len(body) {
			return pendingHigh
		}
		if body[i+1] != 'u' {
			if pendingHigh {
				return true
			}
			i += 2
			continue
		}
		r, ok := hex4Rune(body[i+2:])
		if !ok {
			// encoding/json already accepted this token, so the four hex
			// digits must be present; treat a malformed span defensively as a
			// non-surrogate escape rather than a false positive.
			if pendingHigh {
				return true
			}
			i += 2
			continue
		}
		switch {
		case isHighSurrogate(r):
			if pendingHigh {
				return true // the previous high never received its low
			}
			pendingHigh = true
		case isLowSurrogate(r):
			if !pendingHigh {
				return true // low surrogate without a preceding high
			}
			pendingHigh = false // a complete surrogate pair: legal
		default:
			if pendingHigh {
				return true
			}
		}
		i += 6 // backslash, 'u' and four hex digits
	}
	return pendingHigh
}

// hex4Rune decodes exactly four hexadecimal digits at s[0:4].
func hex4Rune(s []byte) (rune, bool) {
	if len(s) < 4 {
		return 0, false
	}
	var r rune
	for k := 0; k < 4; k++ {
		var d rune
		switch {
		case '0' <= s[k] && s[k] <= '9':
			d = rune(s[k] - '0')
		case 'a' <= s[k] && s[k] <= 'f':
			d = rune(s[k]-'a') + 10
		case 'A' <= s[k] && s[k] <= 'F':
			d = rune(s[k]-'A') + 10
		default:
			return 0, false
		}
		r = r<<4 | d
	}
	return r, true
}

func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }

