52	// rawTokenBytes bounds one token's exact bytes from decoder offsets. A
53	// Token() call consumes the insignificant text before the token as well —
54	// whitespace, and, depending on context, the single ',' separating an array
55	// element or the ':' separating a member name from its value — so those
56	// separator bytes are skipped to reach the token itself.
57	func rawTokenBytes(data []byte, start, end int64) []byte {
58		i := int(start)
59		for i < int(end) && isTokenSeparator(data[i]) {
