70	// accepted: raw is the token's exact bytes in the document (the surrounding
71	// double quotes included) and decoded is the string the decoder produced.
72	// It flags invalid raw UTF-8 and unpaired surrogate escapes. A genuinely
73	// written U+FFFD is indistinguishable from a substitution only after decoding,
74	// which is why the raw token — not the decoded string — is examined.
75	func checkJSONStringToken(raw []byte, _ string) *invalidTextError {
76		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
