93	// excluded) for a \uXXXX escape that is an unpaired UTF-16 surrogate. A high
94	// surrogate escape must be immediately followed by a low surrogate escape and
95	// a low must follow a high; anything in between — another escape, a literal
96	// character, end of string — leaves the surrogate unpaired. A doubled
97	// backslash is an escaped backslash ("\\"), so "\\uD800" leaves the seven
98	// ordinary characters u, D, 8, 0, 0 after consuming the paired backslashes
99	// and is not read as a Unicode escape.
100	func hasUnpairedSurrogate(body []byte) bool {
101		pendingHigh := false
102		for i := 0; i < len(body); {
103			if body[i] != '\\' {
104				if pendingHigh {
105					return true // high surrogate was not immediately followed by its low
106				}
107				_, size := utf8.DecodeRune(body[i:])
108				if size == 0 {
109					size = 1
110				}
111				i += size
112				continue
113			}
114			// body[i] is a backslash introducing (or, for "\\", pairing with) an
115			// escape. A non-unicode escape consumes two bytes total; "\\uD800" is
116			// therefore the two-byte escaped backslash plus literal "uD800".
117			if i+1 >= len(body) {
118				return pendingHigh
119			}
120			if body[i+1] != 'u' {
121				if pendingHigh {
122					return true
123				}
124				i += 2
125				continue
126			}
127			r, ok := hex4Rune(body[i+2:])
128			if !ok {
