130				// digits must be present; treat a malformed span defensively as a
131				// non-surrogate escape rather than a false positive.
132				if pendingHigh {
133					return true
134				}
135				i += 2
136				continue
137			}
138			switch {
139			case isHighSurrogate(r):
140				if pendingHigh {
141					return true // the previous high never received its low
142				}
143				pendingHigh = true
144			case isLowSurrogate(r):
145				if !pendingHigh {
146					return true // low surrogate without a preceding high
147				}
148				pendingHigh = false // a complete surrogate pair: legal
149			default:
150				if pendingHigh {
151					return true
152				}
153			}
154			i += 6 // backslash, 'u' and four hex digits
155		}
156		return pendingHigh
157	}
