160	func hex4Rune(s []byte) (rune, bool) {
161		if len(s) < 4 {
162			return 0, false
163		}
164		var r rune
165		for k := 0; k < 4; k++ {
166			var d rune
167			switch {
168			case '0' <= s[k] && s[k] <= '9':
169				d = rune(s[k] - '0')
